import time, json

DEFAULT_BRANCH = "51A Hồ Tùng Mậu, HN"
BRANCH_WANT = BRANCH or DEFAULT_BRANCH
SEL = {
    "name": 'input[name="your-name"]',
    "phone": 'input[name="phone"]',
    "date": '[name="date"]',
    "adult": 'input[name="adult"]',
    "time": 'select[name="time"]',
    "address": 'select[name="address"]',
    "email": 'input[type="email"],input[name*="mail"]',
}

def q(k):
    return json.dumps(SEL[k])

def wait_until(expr, timeout=15):
    t0 = time.time()
    while time.time() - t0 < timeout:
        if js(expr):
            return True
        time.sleep(0.15)
    return False

def setv(k, val):
    # Gán value cho input/textarea bằng native setter, rồi dispatch input + change
    return js(f"""(()=>{{const e=document.querySelector({q(k)});if(!e)return 'NF';
const p=e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;
Object.getOwnPropertyDescriptor(p,'value').set.call(e,{json.dumps(str(val))});
e.dispatchEvent(new Event('input',{{bubbles:true}}));e.dispatchEvent(new Event('change',{{bubbles:true}}));
return 'OK';}})()""")

def setsel(k, wants):
    # v2: nếu select nằm trong widget .stm_select của theme thì chọn qua widget (bấm ô hiển thị rồi bấm dòng),
    # để phần hiển thị cũng đổi; không có widget thì gán select gốc như cũ.
    r = js(f"""(()=>{{const s=document.querySelector({q(k)});if(!s)return {{st:'NF'}};
const w=s.closest('.stm_select');if(!w)return {{st:'NOWIDGET'}};
const W={json.dumps(wants)};
const o=W.map(x=>[...s.options].find(o=>o.value===x||o.text.trim()===x)).find(Boolean);
if(!o)return {{st:'NOOPT'}};if(o.disabled)return {{st:'DIS'}};
const li=[...w.querySelectorAll('.stm_select__dropdown li')].find(l=>l.textContent.trim()===o.text.trim());
if(!li)return {{st:'NOLI'}};
w.querySelector('.stm-select__val').click();li.click();
const shown=w.querySelector('.stm-select__val').textContent.trim();
if(s.value!==o.value||shown!==o.text.trim())return {{st:'WIDGET_MISMATCH',v:s.value,shown:shown}};
return {{st:'OK',v:o.value}};}})()""")
    if r and r.get("st") != "NOWIDGET":
        return r
    return setsel_native(k, wants)

def setsel_native(k, wants):
    # Khớp CHÍNH XÁC value hoặc text của option, gán select gốc rồi dispatch input + change
    return js(f"""(()=>{{const s=document.querySelector({q(k)});if(!s)return {{st:'NF'}};
const W={json.dumps(wants)};
const hit=W.map(w=>[...s.options].find(o=>o.value===w||o.text.trim()===w)).find(Boolean);
if(!hit)return {{st:'NOOPT'}};if(hit.disabled)return {{st:'DIS'}};
s.value=hit.value;s.dispatchEvent(new Event('input',{{bubbles:true}}));s.dispatchEvent(new Event('change',{{bubbles:true}}));
return {{st:'OK',v:hit.value}};}})()""")

def chk(r, what):
    if not r or r.get("st") != "OK":
        raise RuntimeError(f"UNAVAILABLE: {what} ({r.get('st') if r else 'null'})")
    return r.get("v")

# 1. Chờ form
if not wait_until(f"!!document.querySelector({q('name')}) && !!document.querySelector({q('time')})"):
    raise RuntimeError("UNAVAILABLE: form không xuất hiện")

# 2. Chọn chi nhánh, ngày, số người TRƯỚC (các thao tác này làm tải lại danh sách giờ)
branch_val = chk(setsel("address", [BRANCH_WANT]), f"chi nhánh {BRANCH_WANT}")

kind = js(f"(document.querySelector({q('date')})||{{}}).tagName||null")
if kind == "SELECT":
    label = {1: "Ngày mai", 2: "Ngày kia"}.get(DAY_OFFSET)
    wants = [x for x in [label, DATE_DMY] if x]
    date_val = chk(setsel("date", wants), f"ngày {DATE_DMY}")
else:
    if setv("date", DATE_DMY) == "NF":
        raise RuntimeError("UNAVAILABLE: không tìm thấy ô ngày")
    date_val = DATE_DMY
    js(f"document.querySelector({q('date')}).blur()")

if setv("adult", PARTY) == "NF":
    raise RuntimeError("UNAVAILABLE: không tìm thấy ô số người")
time.sleep(0.3)

# 3. Chờ danh sách giờ ổn định (không đổi trong 0.6s)
t0 = time.time(); prev = None; since = t0
TIME_OPT = json.dumps(SEL["time"] + " option")
while time.time() - t0 < 15:
    cur = js(f"[...document.querySelectorAll({TIME_OPT})].map(o=>o.value)")
    if cur != prev:
        prev, since = cur, time.time()
    elif time.time() - since >= 0.6 and cur and len(cur) > 1:
        break
    time.sleep(0.15)
else:
    raise RuntimeError("UNAVAILABLE: danh sách giờ không ổn định")

# 4. Chọn giờ, điền thông tin liên hệ
chk(setsel("time", [HHMM]), f"giờ {HHMM}")
if setv("name", NAME) == "NF":
    raise RuntimeError("UNAVAILABLE: không tìm thấy ô họ tên")
if setv("phone", PHONE) == "NF":
    raise RuntimeError("UNAVAILABLE: không tìm thấy ô số điện thoại")
if EMAIL:
    setv("email", EMAIL)  # không tồn tại thì bỏ qua

# 5. Đọc lại value thật và đối chiếu
vals = js(f"""(()=>{{const S={json.dumps(SEL)};const r={{}};
for(const k in S){{const e=document.querySelector(S[k]);r[k]=e?e.value:null}}return r}})()""")

exp = {"name": str(NAME), "phone": str(PHONE), "date": date_val,
       "adult": str(PARTY), "time": HHMM, "address": branch_val}
if EMAIL and vals.get("email") is not None:
    exp["email"] = str(EMAIL)

bad = [f"{k}: {vals.get(k)!r} != {v!r}" for k, v in exp.items() if vals.get(k) != v]
# v2: chữ hiển thị trên widget phải khớp giá trị đã chọn
# (theme thay option của select gốc bằng 1 option chữ rỗng, nên so với s.value, không so với chữ của option)
shown = js("""(()=>{const r={};for(const w of document.querySelectorAll('.stm_select')){const s=w.querySelector('select');
const v=w.querySelector('.stm-select__val');if(s&&v)r[s.name]=[s.value.trim(),v.textContent.trim()]}return r})()""")
bad += [f"hiển thị {k}: {b!r} != {a!r}" for k, (a, b) in (shown or {}).items() if k in ("time", "address") and a != b]
if bad:
    raise RuntimeError("MISMATCH: " + "; ".join(bad))
print("OK", vals)

